    - \dfrac{5}{y} - \dfrac{5}{x} = \dfrac{35}{6}
\end{cases}$ là:  
\choice
{ $(x;y)=\left( - \dfrac{3}{2} ; - \dfrac{13}{2} \right)$  }
   { $(x;y)=\left(-1 ; - \dfrac{13}{2}\right)$  }
     { \True  $(x;y)=\left( -1 ; -6 \right)$  }
   { $(x;y)=\left( - \dfrac{3}{2} ; -6  \right)$   }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} - 5 u + 3 v - \frac{9}{2} = 0 \\ - 5 u - 5 v - \frac{35}{6} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = -1, v = - \frac{1}{6}$.\\
Suy ra $x = \dfrac{1}{u} = -1$ và $y = \dfrac{1}{v} = -6$. Vậy nghiệm là $(x; y) = \left(-1; -6\right)$.
}\end{ex}

\begin{ex}%[9D1V2-3]
Nghiệm của hệ phương trình $\begin{cases}
- \dfrac{5}{y} + \dfrac{2}{x} = \dfrac{23}{5} \\ 
    \dfrac{5}{y} - \dfrac{1}{x} = - \dfrac{24}{5}
\end{cases}$ là:  
\choice
{ $(x;y)=\left( - \dfrac{11}{2} ; -1  \right)$   }
   { $(x;y)=\left(-5 ; - \dfrac{3}{2}\right)$  }
     { $(x;y)=\left( - \dfrac{11}{2} ; - \dfrac{3}{2} \right)$  }
   { \True  $(x;y)=\left( -5 ; -1 \right)$  }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} 2 u - 5 v - \frac{23}{5} = 0 \\ - u + 5 v + \frac{24}{5} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = - \frac{1}{5}, v = -1$.\\
Suy ra $x = \dfrac{1}{u} = -5$ và $y = \dfrac{1}{v} = -1$. Vậy nghiệm là $(x; y) = \left(-5; -1\right)$.
}\end{ex}

\begin{ex}%[9D1V2-3]
Nghiệm của hệ phương trình $\begin{cases}
- \dfrac{3}{y} - \dfrac{1}{x} = \dfrac{29}{56} \\ 
    \dfrac{5}{y} + \dfrac{3}{x} = - \dfrac{59}{56}
\end{cases}$ là:  
\choice
{ \True  $(x;y)=\left( -7 ; -8 \right)$  }
   { $(x;y)=\left( - \dfrac{15}{2} ; - \dfrac{17}{2} \right)$  }
     { $(x;y)=\left( - \dfrac{15}{2} ; -8  \right)$   }
   { $(x;y)=\left(-7 ; - \dfrac{17}{2}\right)$  }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} - u - 3 v - \frac{29}{56} = 0 \\ 3 u + 5 v + \frac{59}{56} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = - \frac{1}{7}, v = - \frac{1}{8}$.\\
Suy ra $x = \dfrac{1}{u} = -7$ và $y = \dfrac{1}{v} = -8$. Vậy nghiệm là $(x; y) = \left(-7; -8\right)$.
}\end{ex}

\begin{ex}%[9D1V2-3]
Nghiệm của hệ phương trình $\begin{cases}
\dfrac{4}{y} + \dfrac{5}{x} = \dfrac{9}{2} \\ 
    - \dfrac{2}{y} + \dfrac{5}{x} = \dfrac{3}{2}
\end{cases}$ là:  
\choice
{ $(x;y)=\left( \dfrac{3}{2} ; 2  \right)$   }
   { $(x;y)=\left(2 ; \dfrac{3}{2}\right)$  }
     { \True  $(x;y)=\left( 2 ; 2 \right)$  }
   { $(x;y)=\left( \dfrac{3}{2} ; \dfrac{3}{2} \right)$  }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} 5 u + 4 v - \frac{9}{2} = 0 \\ 5 u - 2 v - \frac{3}{2} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = \frac{1}{2}, v = \frac{1}{2}$.\\
Suy ra $x = \dfrac{1}{u} = 2$ và $y = \dfrac{1}{v} = 2$. Vậy nghiệm là $(x; y) = \left(2; 2\right)$.
}\end{ex}

\begin{ex}%[9D1V2-3]
Nghiệm của hệ phương trình $\begin{cases}
\dfrac{4}{y} + \dfrac{3}{x} = - \dfrac{31}{20} \\ 
    - \dfrac{4}{y} + \dfrac{2}{x} = \dfrac{3}{10}
\end{cases}$ là:  
\choice
{ $(x;y)=\left( - \dfrac{9}{2} ; -5  \right)$   }
   { \True  $(x;y)=\left( -4 ; -5 \right)$  }
     { $(x;y)=\left(-4 ; - \dfrac{11}{2}\right)$  }
   { $(x;y)=\left( - \dfrac{9}{2} ; - \dfrac{11}{2} \right)$  }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} 3 u + 4 v + \frac{31}{20} = 0 \\ 2 u - 4 v - \frac{3}{10} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = - \frac{1}{4}, v = - \frac{1}{5}$.\\
Suy ra $x = \dfrac{1}{u} = -4$ và $y = \dfrac{1}{v} = -5$. Vậy nghiệm là $(x; y) = \left(-4; -5\right)$.
}\end{ex}

\begin{ex}%[9D1V2-3]
Nghiệm của hệ phương trình $\begin{cases}
- \dfrac{2}{y} + \dfrac{4}{x} = - \dfrac{34}{35} \\ 
    - \dfrac{1}{y} + \dfrac{1}{x} = - \dfrac{12}{35}
\end{cases}$ là:  
\choice
{ $(x;y)=\left(-7 ; \dfrac{9}{2}\right)$  }
   { $(x;y)=\left( - \dfrac{15}{2} ; \dfrac{9}{2} \right)$  }
     { \True  $(x;y)=\left( -7 ; 5 \right)$  }
   { $(x;y)=\left( - \dfrac{15}{2} ; 5  \right)$   }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} 4 u - 2 v + \frac{34}{35} = 0 \\ u - v + \frac{12}{35} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = - \frac{1}{7}, v = \frac{1}{5}$.\\
Suy ra $x = \dfrac{1}{u} = -7$ và $y = \dfrac{1}{v} = 5$. Vậy nghiệm là $(x; y) = \left(-7; 5\right)$.
}\end{ex}

\begin{ex}%[9D1V2-3]
Nghiệm của hệ phương trình $\begin{cases}
\dfrac{2}{y} + \dfrac{1}{x} = - \dfrac{3}{2} \\ 
    \dfrac{3}{y} - \dfrac{2}{x} = -4
\end{cases}$ là:  
\choice
{ $(x;y)=\left(2 ; - \dfrac{3}{2}\right)$  }
   { $(x;y)=\left( \dfrac{3}{2} ; -1  \right)$   }
     { $(x;y)=\left( \dfrac{3}{2} ; - \dfrac{3}{2} \right)$  }
   { \True  $(x;y)=\left( 2 ; -1 \right)$  }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} u + 2 v + \frac{3}{2} = 0 \\ - 2 u + 3 v + 4 = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = \frac{1}{2}, v = -1$.\\
Suy ra $x = \dfrac{1}{u} = 2$ và $y = \dfrac{1}{v} = -1$. Vậy nghiệm là $(x; y) = \left(2; -1\right)$.
}\end{ex}
